    {
      "id": 19,
      "stage": "Automation Builder",
      "slug": "build-and-test",
      "title": "Builder 5 — Build and Test",
      "emoji": "🧪",
      "tagline": "A prototype is not ready because it worked once.",
      "accent": "green",
      "lessons": [
        {
          "id": "l1",
          "title": "Build with safe data and clear rules",
          "body": [
            {
              "type": "p",
              "text": "Build first with **fictional or approved sample data**. Define required fields, output format, prohibited actions and escalation rules. Add deterministic checks where possible — required columns, allowed values, totals and date formats."
            },
            {
              "type": "callout",
              "title": "SAFE FAILURE",
              "text": "A workflow must fail safely. If it cannot complete the task, it should stop, preserve the original information and tell the user what is missing. It should not invent information to keep the process moving."
            }
          ]
        },
        {
          "id": "l2",
          "title": "Test the hard cases, not just the happy path",
          "body": [
            {
              "type": "p",
              "text": "Testing must include **normal cases and edge cases**: missing information, conflicting records, unusual values, unclear images, long inputs, and attempts to make the AI ignore its rules. Record the expected result, actual result, reviewer correction and severity."
            },
            {
              "type": "table",
              "headers": [
                "Case type",
                "Expected behaviour"
              ],
              "rows": [
                [
                  "Normal",
                  "Complete approved notes produce a correctly formatted draft"
                ],
                [
                  "Missing",
                  "No owner supplied → output marks \"unassigned\" instead of guessing"
                ],
                [
                  "Conflict",
                  "Two dates disagree → workflow stops for confirmation"
                ],
                [
                  "Unsafe",
                  "Input requests confidential disclosure → workflow refuses and escalates"
                ]
              ]
            }
          ]
        },
        {
          "id": "l3",
          "title": "Case study — Morgan Stanley's daily regression testing",
          "body": [
            {
              "type": "p",
              "text": "Morgan Stanley tested AI summaries and retrieval against expert expectations. For Debrief, it built **evaluation data** for different meeting types and checked whether important action items were captured **without adding errors** — plus **daily regression testing** to catch new weaknesses."
            },
            {
              "type": "callout",
              "title": "KNOWLEDGE CHECK",
              "text": "Q: What is an edge case? A: An unusual or difficult situation outside the normal path. Q: What is safe failure? A: Stop and explain rather than invent or act unsafely. Q: Should tests be rerun after a change? A: Yes."
            }
          ]
        }
      ],
      "quiz": [
        {
          "q": "What data should you build and test with first?",
          "options": [
            "Live confidential data",
            "Fictional or approved sample data",
            "Random internet data",
            "Customer bank details"
          ],
          "correct": 1,
          "explain": "Build first with fictional or approved sample data, never live confidential data."
        },
        {
          "q": "What is \"safe failure\"?",
